import{localizeTeaching}from'./teaching-ui.mjs';
import{installLanguageChoice,restoreScene}from'./teaching-language.mjs';
import{bindSeek}from'./seek-controller.mjs';
// Shared live-player state machine. Subject rendering and geometry remain adapters.
import{sceneAt,playbackState,seekState,beginTrial,endTrial,editTrial,cloneState}from'./interactive-state.mjs';
import{questionClock,advanceQuestion,revealQuestion}from'./question-clock.mjs';
export function mountInteractive({data,renderScene,reportTrial,audioUrl}){
 const $=s=>document.querySelector(s),state=playbackState(),stage=$('#stage'),audio=new Audio(audioUrl),asked=new Set(),answers=new Map(),tools=$('#video-tools');state.time=restoreScene(data);audio.id='interactive-audio';audio.hidden=true;audio.preload='metadata';$('.player').append(audio);
 let playing=false,raf=0,epoch=0,q=null,qKey=null,qTimer=0,qLast=0,lastQ=undefined,drag=null,caption=true,disposed=false,seekController=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const clock=t=>`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;$('#seek').max=data.duration;
 function stopQ(){clearInterval(qTimer);qTimer=0;}
 function holdQ(){stopQ();const scene=sceneAt(data.scenes,state.time);if(!q&&scene.question){q=questionClock();qKey=scene.key;}if(q)q.held=true;$('#countdown').textContent='已暂停自动继续，想好后可以接着看。';}
 function renderQuestion(scene){const key=!state.trial&&scene.question&&state.time>=scene.end-.06?scene.key:null;if(key===lastQ)return;lastQ=key;$('#question').hidden=!key;if(!key)return;const item=scene.question;$('#question-title').textContent=item.prompt;$('#choices').replaceChildren();$('#answer').textContent='';
  item.choices.forEach((text,index)=>{const b=document.createElement('button');b.textContent=text;b.setAttribute('aria-pressed',String(answers.get(key)===index));b.onclick=()=>{const held=!!q?.held;pause();answers.set(key,index);asked.add(key);if(!q||qKey!==key){q=questionClock();qKey=key;}stopQ();if(held){q.phase='explanation';q.left=4;q.held=true;}else{revealQuestion(q);qLast=performance.now();qTimer=setInterval(advanceQ,200);}lastQ=undefined;render();};$('#choices').append(b);});if(answers.has(key))$('#answer').textContent=item.replies[answers.get(key)];
 }
 function render(){const activeRow=stage.contains(document.activeElement)?document.activeElement.closest('[data-row]')?.getAttribute('data-row'):null;const scene=sceneAt(data.scenes,state.time);stage.dataset.scene=scene.key;stage.dataset.time=state.time.toFixed(3);stage.dataset.fraction=String((state.time-scene.start)/(scene.end-scene.start));stage.innerHTML=renderScene(scene,state.time,state.trial,reduced.matches);$('#clock').textContent=clock(state.time)+' / '+clock(data.duration);$('#seek').value=state.time;$('#play').textContent=playing?'暂停':qTimer?'留在本题':'播放';$('#play').setAttribute('aria-label',playing?'暂停讲解':qTimer?'暂停自动继续':'播放讲解');const cue=data.captions.find(c=>state.time>=c.start&&state.time<c.end);$('#caption').textContent=state.trial?'讲解已暂停。试完后回到原处接着看。':cue?.text||'';$('#caption').hidden=!caption;$('#trial-banner').hidden=!state.trial;$('#trial-description').textContent=(scene.trialHint?scene.trialHint+' ':'')+`讲解停在${clock(state.savedTime??state.time)}，返回后可以接着看。`;
 const dragHint=$('#drag-hint');if(dragHint){const boardEl=stage.querySelector('[data-board] [data-row]');dragHint.hidden=!boardEl||state.trial;if(boardEl&&!state.trial)dragHint.textContent=(scene.trialHint?scene.trialHint+' ':'')+'直接拖动图中的模块，检查结果会即时更新；试完点“回到讲解”继续。';}
 const rows=state.trial||scene.rows;const sig=rows.map(r=>r[0]).join('|');if($('#selected').dataset.rows!==sig){$('#selected').replaceChildren(...rows.map((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=r[0]+'（第'+(i+1)+'行）';return o;}));$('#selected').dataset.rows=sig;}$('#selected').value=state.selected<rows.length?state.selected:0;$('#undo').disabled=!state.history.length;
 $('#metrics').textContent=state.trial?reportTrial(state.trial,scene):'点图里的模块，或选择一个模块试一试。';for(const b of document.querySelectorAll('[data-chapter]'))b.setAttribute('aria-current',String(Number(b.dataset.chapter)===scene.chapter));renderQuestion(scene);localizeTeaching(document.body);if(activeRow!=null)stage.querySelector('[data-row="'+activeRow+'"]')?.focus({preventScroll:true});
 }
 function stopDrag(){if(!drag)return;const saved=drag;drag=null;if(state.trial)state.trial=cloneState(saved.rows);try{if(stage.hasPointerCapture(saved.pointerId))stage.releasePointerCapture(saved.pointerId);}catch{}}
 function pause(){seekController?.cancel();stopDrag();playing=false;epoch++;audio.pause();cancelAnimationFrame(raf);raf=0;drag=null;render();}
 function jump(t){pause();locate(t);}
 function locate(t){holdQ();q=null;qKey=null;seekState(state,t,data.duration);audio.currentTime=state.time;for(const s of data.scenes)if(t<s.end){asked.delete(s.key);answers.delete(s.key);}lastQ=undefined;$('#countdown').textContent='播放到这里后，会留出时间让你想一想。';render();}
 function continueQ(){stopQ();q=null;qKey=null;const scene=sceneAt(data.scenes,state.time);if(scene.question){asked.add(scene.key);seekState(state,scene.end,data.duration);}play();}
 function advanceQ(){if(!q||q.held||state.trial||document.hidden)return;const now=performance.now(),action=advanceQuestion(q,(now-qLast)/1000);qLast=now;if(action==='reveal'){const scene=data.scenes.find(s=>s.key===qKey);answers.set(scene.key,scene.question.answer);lastQ=undefined;render();}if(action==='continue'){continueQ();return;}$('#countdown').textContent=q.phase==='thinking'?`${Math.ceil(q.left)}秒后显示答案；也可以点选或留在本题。`:`答案已显示，${Math.ceil(q.left)}秒后继续。`;}
 function tick(){if(!playing||disposed||seekController?.active)return;const next=Math.min(data.duration,audio.currentTime),stop=data.scenes.find(s=>s.question&&!asked.has(s.key)&&state.time<s.end-.02&&next>=s.end-.02);state.time=stop?stop.end-.02:next;if(stop){asked.add(stop.key);audio.currentTime=state.time;pause();q=questionClock();qKey=stop.key;qLast=performance.now();stopQ();qTimer=setInterval(advanceQ,200);advanceQ();render();return;}render();if(state.time>=data.duration-.015){state.time=data.duration;pause();return;}raf=requestAnimationFrame(tick);}
 function play(){seekController?.cancel();stopDrag();holdQ();q=null;qKey=null;if(state.trial)endTrial(state);if(state.time>=data.duration-.015){seekState(state,0,data.duration);asked.clear();answers.clear();}audio.currentTime=state.time;audio.playbackRate=Number($('#speed').value);playing=true;const token=++epoch;render();if(window.parent!==window)parent.postMessage({type:'interactive-play'},location.origin);audio.play().then(()=>{if(playing&&token===epoch){cancelAnimationFrame(raf);raf=requestAnimationFrame(tick);}}).catch(()=>{if(token!==epoch)return;pause();$('#metrics').textContent='播放未能开始，请再点一次播放。也可以按章节查看。';});}
 function begin(index){holdQ();pause();const scene=sceneAt(data.scenes,state.time);beginTrial(state,scene,index);tools.open=true;lastQ=undefined;render();}
 function move(dx,dy){if(!state.trial)begin(Number($('#selected').value));editTrial(state,rows=>{rows[state.selected][1]+=dx;rows[state.selected][2]+=dy;});render();}
 $('#play').onclick=()=>{if(qTimer){holdQ();pause();}else playing?pause():play();};seekController=bindSeek($('#seek'),{isPlaying:()=>playing,pause,seek:locate,play});$('#speed').onchange=()=>audio.playbackRate=Number($('#speed').value);$('#cc').onclick=()=>{caption=!caption;$('#cc').setAttribute('aria-pressed',String(caption));render();};$('#mute').onclick=()=>{audio.muted=!audio.muted;$('#mute').textContent=audio.muted?'开启声音':'静音';};$('#continue').onclick=continueQ;$('#hold').onclick=()=>{holdQ();pause();};$('#return').onclick=()=>{stopDrag();endTrial(state);lastQ=undefined;render();};$('#selected').onchange=()=>begin(Number($('#selected').value));
 for(const b of document.querySelectorAll('[data-move]'))b.onclick=()=>move(...b.dataset.move.split(',').map(Number));$('#undo').onclick=()=>{if(state.history.length)state.trial=state.history.pop();render();};$('#reset').onclick=()=>{if(state.trial){state.trial=cloneState(sceneAt(data.scenes,state.savedTime).rows);state.history=[];render();}};
 const select=$('#steps');for(const s of data.scenes){const o=document.createElement('option');o.value=s.start;o.textContent=clock(s.start)+' '+s.title;select.append(o);}select.onchange=()=>jump(Number(select.value));$('#step-end').onclick=()=>jump(sceneAt(data.scenes,state.time).end-.05);
 data.chapters.forEach((title,i)=>{const s=data.scenes.find(s=>s.chapter===i+1);if(!s)return;const b=document.createElement('button');b.textContent=clock(s.start)+' '+(i+1)+'. '+title;b.dataset.chapter=i+1;b.onclick=()=>jump(s.start);$('#chapters').append(b);});
 stage.addEventListener('keydown',e=>{const row=e.target.closest('[data-row]');if(!row)return;const index=Number(row.dataset.row);if(e.key==='Enter'||e.code==='Space'){e.preventDefault();begin(index);}const d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,1],ArrowDown:[0,-1]}[e.key];if(d){e.preventDefault();if(!state.trial||state.selected!==index)begin(index);move(...d);}});
 stage.addEventListener('pointerdown',e=>{const row=e.target.closest('[data-row]');if(!row)return;const index=Number(row.dataset.row);begin(index);const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(stage.getScreenCTM().inverse()),board=stage.querySelector('[data-board]');drag={index,p,rows:cloneState(state.trial),unit:Number(board?.dataset.unit)||35,pointerId:e.pointerId};stage.querySelector('[data-row="'+index+'"]')?.focus({preventScroll:true});stage.setPointerCapture(e.pointerId);e.preventDefault();});
 stage.addEventListener('pointermove',e=>{if(!drag)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(stage.getScreenCTM().inverse());state.trial=cloneState(drag.rows);state.trial[drag.index][1]+=Math.round((p.x-drag.p.x)/drag.unit);state.trial[drag.index][2]-=Math.round((p.y-drag.p.y)/drag.unit);render();});stage.addEventListener('pointerup',()=>{const saved=drag;drag=null;if(saved&&JSON.stringify(state.trial)!==JSON.stringify(saved.rows))state.history.push(saved.rows);if(saved)try{stage.releasePointerCapture(saved.pointerId);}catch{}render();});stage.addEventListener('pointercancel',()=>{stopDrag();render();});
 $('#fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():$('.player').requestFullscreen();$('#go-lab').onclick=()=>{holdQ();pause();if(parent!==window)parent.postMessage({type:'interactive-go-lab'},location.origin);else location.href='../#lab';};
 const onHidden=()=>{if(document.hidden){holdQ();pause();}},onMessage=e=>{if(e.origin===location.origin&&e.source===parent&&e.data?.type==='interactive-pause'){holdQ();pause();}};document.addEventListener('visibilitychange',onHidden);window.addEventListener('message',onMessage);const size=new ResizeObserver(()=>{if(parent!==window)parent.postMessage({type:'interactive-height',height:Math.ceil(document.body.getBoundingClientRect().height)},location.origin);});size.observe(document.body);
 const dispose=()=>{seekController?.dispose();stopDrag();disposed=true;holdQ();playing=false;epoch++;audio.pause();cancelAnimationFrame(raf);drag=null;size.disconnect();document.removeEventListener('visibilitychange',onHidden);window.removeEventListener('message',onMessage);};window.addEventListener('pagehide',dispose,{once:true});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});audio.addEventListener('ended',()=>{if(!seekController?.active&&Number.isFinite(audio.duration)&&Math.abs(audio.currentTime-audio.duration)<.1){state.time=data.duration;pause();}});audio.addEventListener('error',()=>{pause();$('#metrics').textContent='音频读取失败，请刷新后重试。';});installLanguageChoice(()=>{const s=sceneAt(data.scenes,state.time);return{key:s.key,fraction:(state.time-s.start)/(s.end-s.start)};});$('#play').disabled=false;render();return{pause,dispose};
}
